export type UsersQuery = {
    page: number; // 0-based, as the API expects
    size: number;
    search?: string;
    userType?: string;
    staffType?: string;
    isActive?: boolean;
    sortBy?: string;
    sortDir?: "asc" | "desc";
};

/**
 * One page of users, filtered and sorted by the server.
 *
 * The same `/users/get` endpoint still returns the full array when no `page` is sent, so a
 * frontend deployed ahead of the backend gets a plain list back rather than a paged envelope.
 * Callers must handle both shapes - see `readUsersPage`.
 */
export const useGetUsersPaged = (query: UsersQuery) =>
    useApiGet<{ data: TenantUserResponsePojo[] }>(`/users/get`, {
        queryParams: {
            page: query.page,
            size: query.size,
            ...(query.search ? { search: query.search } : {}),
            ...(query.userType ? { userType: query.userType } : {}),
            ...(query.staffType ? { staffType: query.staffType } : {}),
            ...(query.isActive !== undefined ? { isActive: query.isActive } : {}),
            ...(query.sortBy ? { sortBy: query.sortBy, sortDir: query.sortDir ?? "asc" } : {}),
        },
        retry: 0,
    });

/**
 * Normalises whichever shape came back.
 *
 * `paged` is false when the server ignored the page parameter and returned everything, which
 * is what a not-yet-updated backend does - the caller then filters and pages client-side as
 * it always did.
 */
export const readUsersPage = <T,>(payload: any): { rows: T[]; totalCount: number; paged: boolean } => {
    if (Array.isArray(payload)) return { rows: payload, totalCount: payload.length, paged: false };
    if (payload && Array.isArray(payload.data)) {
        return { rows: payload.data, totalCount: payload.totalCount ?? payload.data.length, paged: true };
    }
    return { rows: [], totalCount: 0, paged: false };
};

