/**
 * Address suggestions, looked up by the backend.
 *
 * This used to be the Google Maps JavaScript SDK running in the browser, which requires the
 * API key to be present in the shipped bundle where anyone can read it. The key now lives
 * only on the server.
 *
 * `sessionToken` groups a run of keystrokes and the place-details call that follows into one
 * billable Google session - without it every keystroke is charged separately.
 */
export const useSearchAddresses = (
    input: string,
    region: string | undefined,
    sessionToken: string
) =>
    useApiGet<{ data: AddressSearchResult }>(`/google/place`, {
        enabled: input.trim().length >= 3,
        retry: 0,
        // Without this the global loading overlay flashes on every keystroke.
        axiosConfig: { showLoading: false },
        // Suggestions for a given string do not change minute to minute, and this is re-read
        // as the user types back and forth over a word.
        staleTime: 60_000,
        gcTime: 60_000,
        queryParams: { input, region, sessionToken },
    });

/**
 * The browser key for the site map, fetched after login rather than compiled in.
 *
 * An interactive Google map cannot be proxied - the Maps JavaScript API runs in the page and
 * calls Google directly - so this key does reach the browser. Fetching it keeps it out of the
 * static JS bundle, which is where automated scanners harvest these, and lets it be rotated
 * without a frontend rebuild. It is still readable by any signed-in user; the control that
 * stops another site using it is the referrer restriction on the key itself.
 */
export const useGoogleMapsKey = () =>
    useApiGet<{ data: { mapsApiKey: string } }>(`/google/maps-key`, {
        retry: 0,
        // The key does not change between page loads; refetching it would be pure noise.
        staleTime: Infinity,
        gcTime: Infinity,
        axiosConfig: { showLoading: false },
    });

export type PlaceSuggestion = {
    placeId: string;
    description: string;
};

/**
 * Suggestions plus whether the lookup itself worked.
 *
 * An empty list on its own is ambiguous. When the configured Google key was rejected, the
 * dropdown said "no matching addresses" - which reads as "that address does not exist"
 * rather than "this feature is not working", and sent people looking for the wrong problem.
 */
export type AddressSearchResult = {
    suggestions: PlaceSuggestion[];
    lookupAvailable: boolean;
};

