/**
 * Every logo on a client list in one request, as base64 keyed by company id.
 *
 * The per-company hook above costs one request per card, so a list of 50 clients opened 50
 * connections before it looked finished. Callers should treat this as an optimisation and
 * keep the single-logo path as a fallback: if the batch endpoint is missing (a frontend
 * deployed ahead of its backend) this query simply errors and the per-card requests take
 * over, rather than the list rendering with no logos at all.
 *
 * A company with no logo comes back as an explicit null, which is different from absent.
 */
export const useGetCompanyLogos = (companyIds: number[]) =>
    useApiGet<{ data: Record<string, string | null> }>(`/company/logos`, {
        queryParams: { ids: companyIds.join(",") },
        enabled: companyIds.length > 0,
        retry: 0,
        // Logos essentially never change, and this is re-read on every filter keystroke.
        staleTime: 5 * 60 * 1000,
        gcTime: 5 * 60 * 1000,
    });
