export const useGetPayrollStaff = () => useApiGet<{ data: DropDownPojo[] }>("/staff-payroll/get-staff", { retry: 0 });
export const useGetPayslipsByPayroll = (payrollId: number | null) =>
    // One pay run is one staff member, so this is a single payslip (or null if none yet).
    useApiGet<{ data: PayslipResPojo | null }>(`/payslip/by-payroll/${payrollId}`, { enabled: !!payrollId, retry: 0 });
export const useRegeneratePayslips = () =>
    useApiMutation<unknown, unknown, ApiVariables<unknown> & { payrollId: number | string }>("post", (vars) => `/payslip/regenerate/${vars.payrollId}`);
export const useGetMyPayslips = () => useApiGet<{ data: PayslipResPojo[] }>("/payslip/me", { retry: 0 });
export const useGetMyLeaveBalance = () => useApiGet<{ data: StaffLeaveBalanceResPojo }>("/leave-balance/me", { retry: 0 });
export const useGetLeaveBalance = (staffId: string | null) =>
    useApiGet<{ data: StaffLeaveBalanceResPojo }>(`/leave-balance/${staffId}`, { enabled: !!staffId, retry: 0 });
export const useGetPayrollAwardSettings = () => useApiGet<{ data: PayrollAwardSettingsResPojo }>("/payroll-award-settings", { retry: 0 });
export const useUpdatePayrollAwardSettings = () => useApiMutation<unknown>("put", "/payroll-award-settings");
export const useGetStpStatus = () => useApiGet<{ data: Record<string, unknown> }>("/stp/status", { retry: 0 });
export const useSubmitStp = () =>
    useApiMutation<unknown, unknown, ApiVariables<unknown> & { payslipId: number | string }>("post", (vars) => `/stp/submit/${vars.payslipId}`);
export const useGetStpLog = (payslipId: number | null) =>
    useApiGet<{ data: StpSubmissionLogResPojo[] }>(`/stp/log/${payslipId}`, { enabled: !!payslipId, retry: 0 });
export const useGetApprovalRules = (entityType: "EXPENSE_CLAIM" | "PURCHASE_ORDER" | "LEAVE_REQUEST") =>
    useApiGet<{ data: ApprovalChainRuleResPojo[] }>(`/approval-chain/rules/${entityType}`, { retry: 0 });
export const useSaveApprovalRule = () => useApiMutation<unknown>("post", "/approval-chain/rules");
export const useDeleteApprovalRule = () =>
    useApiMutation<unknown, unknown, ApiVariables<unknown> & { id: number | string }>("delete", (vars) => `/approval-chain/rules/${vars.id}`);
